// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading
const { fontFamily: montserratFamily } = loadMontserrat();



export type ObjectionRejectionProps = Record<string, any>;

const renderIcon = (type: string) => {
  const style = { width: 90, height: 90, color: "rgba(255, 255, 255, 0.7)", marginBottom: 30 };
  switch (type) {
    case "network":
      return (
        <svg style={style} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
          <circle cx="18" cy="5" r="3" />
          <circle cx="6" cy="12" r="3" />
          <circle cx="18" cy="19" r="3" />
          <line x1="8.59" y1="13.51" x2="15.42" y2="17.49" />
          <line x1="15.41" y1="6.51" x2="8.59" y2="10.49" />
        </svg>
      );
    case "badge":
      return (
        <svg style={style} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
          <circle cx="12" cy="8" r="7" />
          <polyline points="8.21 13.89 7 23 12 20 17 23 15.79 13.88" />
        </svg>
      );
    case "checklist":
      return (
        <svg style={style} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
          <polyline points="9 11 12 14 22 4" />
          <path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11" />
        </svg>
      );
    default:
      return null;
  }
};

const ObjectionRejectionSequence: React.FC<ObjectionRejectionProps> = ({
  backgroundColor = "#0B001A",
  transparentBackground = false,
  durationInSeconds = 6,
  rejectedCards = [
    { label: "DOWNLINES", icon: "network" },
    { label: "RANKS", icon: "badge" },
    { label: "QUALIFICATIONS", icon: "checklist" }
  ],
  stampText = "REJECTED",
  stampColor = "#E63946",
  replacementCards = [
    { title: "$100 COMMISSIONS", badge: "" },
    { title: "$300 COMMISSIONS", badge: "OPTIONAL" }
  ],
  replacementSublabel = "INSTANT. DIRECT. LEVERAGED.",
  goldColorStart = "#FFDF00",
  goldColorEnd = "#D4AF37",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // ----------------------------------------
  // LAYOUT CALCULATIONS
  // ----------------------------------------
  const rCardW = 380;
  const rCardH = 480;
  const rCardGap = 80;
  const totalRWidth = (rejectedCards.length * rCardW) + ((rejectedCards.length - 1) * rCardGap);
  const rStartX = (width - totalRWidth) / 2;
  const rCenterY = (height - rCardH) / 2;

  const gCardW = 550;
  const gCardH = 350;
  const gCardGap = 60;
  const totalGWidth = (replacementCards.length * gCardW) + ((replacementCards.length - 1) * gCardGap);
  const gStartX = (width - totalGWidth) / 2;
  const gCenterY = (height - gCardH) / 2 - 40; // Shifted up slightly to fit sublabel

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor, fontFamily: montserratFamily, overflow: "hidden" }}>
      
      {/* 1. REJECTED CARDS SEQUENCE */}
      {rejectedCards.map((card, idx) => {
        // Timings
        const enterSpring = spring({ fps, frame: frame - (idx * 10), config: { damping: 14, stiffness: 80 } });
        const enterY = interpolate(enterSpring, [0, 1], [1000, 0]);
        const enterOpacity = interpolate(enterSpring, [0, 0.5], [0, 1]);

        const slamFrame = 45 + (idx * 30);
        const hitFrame = slamFrame + 6; // Approx frame when stamp hits scale 1

        const stampSpr = spring({ fps, frame: frame - slamFrame, config: { damping: 12, stiffness: 220 } });
        const stampScale = interpolate(stampSpr, [0, 1], [4, 1]);
        const stampOpacity = interpolate(stampSpr, [0, 0.3], [0, 1], { extrapolateRight: "clamp" });

        const isShaking = frame >= hitFrame && frame < hitFrame + 15;
        const shakeX = isShaking
          ? interpolate(frame - hitFrame, [0, 3, 6, 9, 12, 15], [0, -15, 15, -10, 10, 0], { extrapolateRight: "clamp" })
          : 0;

        const fallSpr = spring({ fps, frame: frame - hitFrame - 2, config: { damping: 15, mass: 1.5, stiffness: 90 } });
        const fallY = fallSpr * 1200;
        const fallX = fallSpr * -300;
        const fallRot = fallSpr * -35;
        const fallOpacity = interpolate(fallSpr, [0, 0.8], [1, 0], { extrapolateRight: "clamp" });
        const fallBlur = interpolate(fallSpr, [0, 1], [0, 20]);

        const cardLeft = rStartX + idx * (rCardW + rCardGap);

        return (
          <div
            key={`rej-${idx}`}
            style={{
              position: "absolute",
              left: cardLeft,
              top: rCenterY,
              width: rCardW,
              height: rCardH,
              transform: `translate(${shakeX + fallX}px, ${enterY + fallY}px) rotate(${fallRot}deg)`,
              opacity: enterOpacity * fallOpacity,
              filter: `blur(${fallBlur}px)`,
              transition: "none",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              zIndex: 10 - idx,
            }}
          >
            {/* GLASS CARD BACKGROUND */}
            <div style={{
              position: "absolute",
              inset: 0,
              backgroundColor: "rgba(255, 255, 255, 0.03)",
              border: "1px solid rgba(255, 255, 255, 0.08)",
              borderRadius: 30,
              backdropFilter: "blur(16px)",
              WebkitBackdropFilter: "blur(16px)",
              boxShadow: "0 20px 40px rgba(0,0,0,0.4)",
              transition: "none"
            }} />

            {/* CARD CONTENT */}
            <div style={{ position: "relative", zIndex: 2, display: "flex", flexDirection: "column", alignItems: "center", transition: "none" }}>
              {renderIcon(card.icon)}
              <div style={{
                color: "rgba(255, 255, 255, 0.8)",
                fontSize: 28,
                fontWeight: 600,
                letterSpacing: 4,
                textAlign: "center",
                transition: "none"
              }}>
                {card.label}
              </div>
            </div>

            {/* PARTICLES ON IMPACT */}
            {Array.from({ length: 8 }).map((_, pIdx) => {
              const angle = (pIdx / 8) * Math.PI * 2;
              const dist = fallSpr * 300;
              const px = Math.cos(angle) * dist;
              const py = Math.sin(angle) * dist;
              const pScale = interpolate(fallSpr, [0, 0.1, 1], [0, 1.5, 0], { extrapolateRight: "clamp" });
              
              return (
                <div key={`p-${pIdx}`} style={{
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  width: 16,
                  height: 16,
                  backgroundColor: stampColor,
                  borderRadius: "50%",
                  transform: `translate(-50%, -50%) translate(${px}px, ${py}px) scale(${pScale})`,
                  opacity: pScale,
                  boxShadow: `0 0 20px ${stampColor}`,
                  zIndex: 1,
                  transition: "none"
                }} />
              );
            })}

            {/* REJECTION STAMP */}
            {frame >= slamFrame && (
              <div style={{
                position: "absolute",
                top: "50%",
                left: "50%",
                transform: `translate(-50%, -50%) scale(${stampScale}) rotate(-15deg)`,
                opacity: stampOpacity,
                border: `8px solid ${stampColor}`,
                color: stampColor,
                fontSize: 48,
                fontWeight: 900,
                padding: "10px 30px",
                borderRadius: 20,
                letterSpacing: 2,
                textTransform: "uppercase",
                boxShadow: `0 0 40px ${stampColor}40, inset 0 0 20px ${stampColor}40`,
                textShadow: `0 0 10px ${stampColor}80`,
                zIndex: 10,
                pointerEvents: "none",
                transition: "none"
              }}>
                {stampText}
              </div>
            )}
          </div>
        );
      })}

      {/* 2. REPLACEMENT GOLD CARDS SEQUENCE */}
      {replacementCards.map((card, idx) => {
        const replStart = 135 + (idx * 15);
        const upSpr = spring({ fps, frame: frame - replStart, config: { damping: 15, stiffness: 90 } });
        const yOff = interpolate(upSpr, [0, 1], [800, 0]);
        const opacity = interpolate(upSpr, [0, 0.5], [0, 1], { extrapolateRight: "clamp" });
        
        const shineSpr = spring({ fps, frame: frame - replStart - 20, config: { damping: 30, mass: 2, stiffness: 40 } });
        const shineLeft = interpolate(shineSpr, [0, 1], [-150, 200]); // Percentage

        const gCardLeft = gStartX + idx * (gCardW + gCardGap);

        return (
          <div
            key={`gold-${idx}`}
            style={{
              position: "absolute",
              left: gCardLeft,
              top: gCenterY,
              width: gCardW,
              height: gCardH,
              transform: `translateY(${yOff}px)`,
              opacity,
              background: `linear-gradient(135deg, ${goldColorStart}, ${goldColorEnd}, ${goldColorStart})`,
              borderRadius: 32,
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              alignItems: "center",
              boxShadow: "0 30px 60px rgba(0,0,0,0.6), inset 0 2px 4px rgba(255,255,255,0.6)",
              border: "2px solid rgba(255,255,255,0.4)",
              overflow: "hidden",
              transition: "none",
              zIndex: 20
            }}
          >
            {/* OPTIONAL BADGE */}
            {card.badge && (
              <div style={{
                position: "absolute",
                top: 24,
                right: 24,
                background: "rgba(0,0,0,0.85)",
                color: goldColorStart,
                padding: "8px 20px",
                borderRadius: 20,
                fontSize: 16,
                fontWeight: 800,
                letterSpacing: 2,
                boxShadow: "0 4px 12px rgba(0,0,0,0.3)",
                transition: "none"
              }}>
                {card.badge}
              </div>
            )}

            {/* CARD TITLE */}
            <div style={{
              color: "#1A1100",
              fontSize: 52,
              fontWeight: 900,
              textAlign: "center",
              padding: "0 40px",
              lineHeight: 1.2,
              textShadow: "0 2px 10px rgba(255,255,255,0.4)",
              transition: "none"
            }}>
              {card.title.split(" ").map((word, wIdx) => (
                <div key={wIdx} style={{ transition: "none" }}>{word}</div>
              ))}
            </div>

            {/* SHINE SWEEP EFFECT */}
            <div style={{
              position: "absolute",
              top: 0,
              left: `${shineLeft}%`,
              width: "50%",
              height: "100%",
              background: "linear-gradient(to right, transparent, rgba(255,255,255,0.7), transparent)",
              transform: "skewX(-25deg)",
              pointerEvents: "none",
              transition: "none"
            }} />
          </div>
        );
      })}

      {/* 3. FINAL SUBLABEL */}
      {(() => {
        const labelStart = 160;
        const labelSpr = spring({ fps, frame: frame - labelStart, config: { damping: 14, stiffness: 80 } });
        const labelY = interpolate(labelSpr, [0, 1], [100, 0]);
        const labelOpacity = interpolate(labelSpr, [0, 0.8], [0, 1], { extrapolateRight: "clamp" });

        return (
          <div style={{
            position: "absolute",
            top: gCenterY + gCardH + 60,
            left: 0,
            width: "100%",
            textAlign: "center",
            transform: `translateY(${labelY}px)`,
            opacity: labelOpacity,
            transition: "none",
            zIndex: 30
          }}>
            <h2 style={{
              margin: 0,
              color: "#FFFFFF",
              fontSize: 36,
              fontWeight: 700,
              letterSpacing: 10,
              textShadow: `0 0 20px ${goldColorStart}80`,
              transition: "none"
            }}>
              {replacementSublabel}
            </h2>
          </div>
        );
      })()}
      
    </AbsoluteFill>
  );
};

export default ObjectionRejectionSequence;